14	/// Fetches the full, unfiltered list of every tag name in the repository at
15	/// `root`, via [`GitAccess`] (native gix, falling back to a `CommandRunner`-
16	/// shelled `git tag --list` when gix is unavailable -- most notably on
17	/// `wasm32`).
18	///
19	/// Deliberately fetches with no glob pattern (the full tag list): callers
20	/// apply their own glob filtering afterwards via [`matching_tags`], using
21	/// the exact same `globset` matcher both `GitDataSource` backends use
22	/// internally. This guarantees identical tag-selection semantics
23	/// regardless of which backend sourced the raw list, and lets the fetch be
24	/// batched once across every package (see [`TagIndex::build`]) instead of
25	/// once per package -- important on `wasm32`, where each `CommandRunner`
26	/// call is a full Extism guest<->host round-trip.
27	fn fetch_all_tags(git: &GitAccess<'_>) -> Result<Vec<String>, GraphError> {
28	    let tags = git.list_tags(None)?;
29	    Ok(tags.into_iter().map(|t| t.0).collect())
30	}
31	
32	/// Filters `all_tags` down to those matching `template`'s glob.
33	///
34	/// Uses the same `globset::Glob`-based matching
35	/// `callisto_vcs::GitRepository::list_tags` applies internally, kept in
36	/// sync deliberately so tag selection is byte-identical whether `all_tags`
37	/// was sourced via gix or the `CommandRunner` fallback in
38	/// [`fetch_all_tags`]. This includes error behavior: a `template.glob()`
39	/// that fails to compile is surfaced as `Err(GraphError::Vcs(VcsError::
40	/// InvalidGlob))`, matching every tag being the unsafe alternative -- a
41	/// malformed tag template must never silently make "last tag" resolution
42	/// pick an unrelated package's tag.
43	fn matching_tags<'a>(
44	    all_tags: &'a [String],
45	    template: &TagTemplate,
46	) -> Result<Vec<&'a str>, GraphError> {
47	    let glob = template.glob();
48	    let matcher = globset::Glob::new(&glob)
49	        .map(|g| g.compile_matcher())
50	        .map_err(|e| {
51	            GraphError::Vcs(callisto_vcs::VcsError::InvalidGlob {
52	                pattern: glob.clone(),
53	                message: e.to_string(),
54	            })
55	        })?;
56	
57	    Ok(all_tags
58	        .iter()
59	        .filter(|t| matcher.is_match(t.as_str()))
60	        .map(|s| s.as_str())
61	        .collect())
62	}
63	
64	/// Selects the highest-versioned tag matching `template` out of a full tag
65	/// list previously obtained via [`fetch_all_tags`].
66	fn select_from_tags(
67	    all_tags: &[String],
68	    template: &TagTemplate,
69	    grammar: VersionGrammar,
70	) -> Result<LastTagSelection, GraphError> {
71	    let candidates = matching_tags(all_tags, template)?;
72	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
73	}
