75	/// Resolves the last release tag matching a single package's `template`.
76	///
77	/// Kept for API compatibility with existing callers, and safe to use
78	/// standalone. Note that this re-fetches the full tag list (gix discovery
79	/// or a `CommandRunner` round-trip) on every call; callers resolving tags
80	/// for many packages at once -- notably [`TagIndex::build`] -- fetch the
81	/// list once and reuse it across packages rather than calling this
82	/// function in a loop.
83	pub fn last_tag_for<R: CommandRunner>(
84	    runner: &R,
85	    root: &Path,
86	    template: &TagTemplate,
87	    grammar: VersionGrammar,
88	) -> Result<LastTagSelection, GraphError> {
89	    let git = GitAccess::discover(root, runner);
90	    let all_tags = fetch_all_tags(&git)?;
91	    select_from_tags(&all_tags, template, grammar)
92	}
