101	impl TagIndex {
102	    pub fn build<D: DependencyResolver>(
103	        git: &GitAccess<'_>,
104	        graph: &D,
105	        _cfg: &ResolvedConfig,
106	    ) -> Result<Self, GraphError> {
107	        let mut last = BTreeMap::new();
108	        let mut templates = BTreeMap::new();
109	        let mut pre_cursor = BTreeMap::new();
110	        let diagnostics = Vec::new();
111	
112	        // Fetch the raw tag list exactly once for the whole build, not once
113	        // per package -- see `fetch_all_tags` for why (avoids N gix
114	        // discoveries / N host round-trips for N packages). `git` is shared
115	        // with the caller rather than discovered fresh here, so a single
116	        // `Workspace`-scoped command that also needs git for other reasons
117	        // (e.g. `plan_publish`'s head_sha resolution) doesn't pay for a
118	        // second discovery.
119	        let all_tags = fetch_all_tags(git)?;
120	
121	        for pkg in graph.packages() {
122	            let default_tmpl =
123	                TagTemplate::parse(&format!("{}@{{version}}", pkg.id.display_name()))?;
124	            let tmpl = pkg.tag_template.clone().unwrap_or(default_tmpl);
125	            let sel = select_from_tags(&all_tags, &tmpl, pkg.version_grammar()?)?;
126	            last.insert(pkg.id.clone(), sel.chosen);
127	            templates.insert(pkg.id.clone(), tmpl);
128	            pre_cursor.insert(pkg.id.clone(), None);
129	        }
130

