53	/// Narrows a [`VcsError`] to the Layer 1 [`CommitWalkError`] vocabulary at
54	/// the [`CommitWalker`] boundary.
55	///
56	/// [`CommitWalkError::Command`] and [`CommitWalkError::RefNotFound`] survive
57	/// as themselves -- they are the two distinctions consumers branch on. Every
58	/// other variant is gix- or repository-specific with no Layer 1 equivalent,
59	/// so it collapses into [`CommitWalkError::Backend`] carrying this error's
60	/// own `Display` rendering; nothing is lost from the message a user sees.
61	impl From<VcsError> for CommitWalkError {
62	    fn from(err: VcsError) -> Self {
63	        match err {
64	            VcsError::Command(inner) => CommitWalkError::Command(inner),
65	            VcsError::RefNotFound { ref_name } => CommitWalkError::RefNotFound { ref_name },
66	            other => CommitWalkError::Backend {
67	                message: other.to_string(),
68	            },
69	        }
70	    }
71	}
