165	/// Wires a [`GitDataSource`] backend up to the Layer 1
166	/// [`callisto_model::CommitWalker`] contract.
167	///
168	/// The bodies are identical for every backend -- delegate `commits_since` and
169	/// narrow [`VcsError`] to [`CommitWalkError`] -- but they cannot be written
170	/// once as a blanket `impl<T: GitDataSource> CommitWalker for T`: `CommitWalker`
171	/// is foreign to this crate and `T` is uncovered, which the orphan rules
172	/// forbid. The macro keeps the repetition honest instead.
173	macro_rules! impl_commit_walker {
174	    ($ty:ty) => {
175	        impl CommitWalker for $ty {
176	            fn commits_since(
177	                &self,
178	                since_ref: Option<&str>,
179	                pathspecs: &[PathBuf],
180	            ) -> Result<Vec<CommitRecord>, CommitWalkError> {
181	                GitDataSource::commits_since(self, since_ref, pathspecs).map_err(Into::into)
182	            }
183	        }
184	    };
185	}
