232	    pub fn list_tags(&self, glob_pattern: Option<&str>) -> Result<Vec<TagName>, VcsError> {
233	        #[cfg(not(target_arch = "wasm32"))]
234	        {
235	            let platform = self
236	                .repo
237	                .references()
238	                .map_err(|e| VcsError::Git(format!("Failed to read references: {e}")))?;
239	
240	            let mut tags = Vec::new();
241	            let tag_refs = platform
242	                .tags()
243	                .map_err(|e| VcsError::Git(format!("Failed to list tag refs: {e}")))?;
244	
245	            // A pattern that fails to compile must not silently disable
246	            // filtering (which would match every tag in the repo -- a real
247	            // correctness risk for release tagging, since a malformed tag
248	            // template could then make "last tag" resolution pick an
249	            // unrelated package's tag). Surface it as an error instead;
250	            // `None` (no pattern requested at all) still means "match
251	            // everything".
252	            let matcher = glob_pattern
253	                .map(|p| {
254	                    globset::Glob::new(p)
255	                        .map(|g| g.compile_matcher())
256	                        .map_err(|e| VcsError::InvalidGlob {
257	                            pattern: p.to_string(),
258	                            message: e.to_string(),
259	                        })
260	                })
261	                .transpose()?;
262	
263	            for r in tag_refs.flatten() {
264	                let name = r.name().shorten().to_string();
265	                if let Some(ref m) = matcher {
266	                    if !m.is_match(&name) {
267	                        continue;
268	                    }
269	                }
270	                tags.push(TagName(name));
271	            }
272	
273	            Ok(tags)
274	        }
275	        #[cfg(target_arch = "wasm32")]
276	        {
277	            let _unused = glob_pattern;
278	            Ok(Vec::new())
279	        }
280	    }
