282	    /// Resolves an arbitrary ref (tag, branch, or partial SHA) to the commit
283	    /// SHA it points at.
284	    ///
285	    /// Follows the same resolution and error-handling convention as the
286	    /// `from_ref` handling inside [`Self::commits_since`]: an unresolvable
287	    /// ref (missing tag, unborn repo, ref pointing at a non-commit object
288	    /// that can't be peeled to one, etc.) is not an error condition -- it
289	    /// degrades gracefully to `Ok(None)`, which callers treat as "no bound"
290	    /// / "infer over full history".
291	    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
292	        #[cfg(not(target_arch = "wasm32"))]
293	        {
294	            let Ok(spec) = self.repo.rev_parse_single(refname) else {
295	                return Ok(None);
296	            };
297	            let Ok(object) = spec.object() else {
298	                return Ok(None);
299	            };
300	            let Ok(commit) = object.peel_to_kind(gix::object::Kind::Commit) else {
301	                return Ok(None);
302	            };
303	
304	            let hex = commit.id.to_hex().to_string();
305	            let sha = CommitSha::parse(&hex)
306	                .map_err(|e| VcsError::Git(format!("Invalid commit SHA: {e}")))?;
307	            Ok(Some(sha))
308	        }
309	        #[cfg(target_arch = "wasm32")]
310	        {
311	            let _unused = refname;
312	            Ok(None)
313	        }
314	    }
