434	    pub fn create_tag(
435	        &self,
436	        name: &str,
437	        target_sha: &CommitSha,
438	        message: Option<&str>,
439	        _permit: &ApplyPermit,
440	    ) -> Result<(), VcsError> {
441	        #[cfg(not(target_arch = "wasm32"))]
442	        {
443	            let oid = gix::ObjectId::from_hex(target_sha.as_ref().as_bytes())
444	                .map_err(|e| VcsError::Git(format!("Invalid SHA: {e}")))?;
445	
446	            if let Some(msg) = message {
447	                self.repo
448	                    .tag(
449	                        name,
450	                        oid,
451	                        gix::object::Kind::Commit,
452	                        None,
453	                        msg,
454	                        gix::refs::transaction::PreviousValue::MustNotExist,
455	                    )
456	                    .map_err(|e| VcsError::Git(format!("Failed to create tag: {e}")))?;
457	            } else {
458	                let clean_name = name.strip_prefix("refs/tags/").unwrap_or(name);
459	                let ref_name = format!("refs/tags/{}", clean_name);
460	                let _unused = self
461	                    .repo
462	                    .reference(
463	                        ref_name,
464	                        oid,
465	                        gix::refs::transaction::PreviousValue::MustNotExist,
466	                        "callisto create tag",
467	                    )
468	                    .map_err(|e| VcsError::Git(format!("Failed to create lightweight tag: {e}")))?;
469	            }
470	            Ok(())
471	        }
472	        #[cfg(target_arch = "wasm32")]
473	        {
474	            let _ = (name, target_sha, message);
475	            Err(VcsError::Git("WASM unsupported".to_string()))
476	        }
477	    }
