511	/// Diffs `commit_obj`'s tree against its first parent's tree (or the empty
512	/// tree, for a root commit) and reports whether any changed path falls
513	/// under one of `pathspecs`.
514	#[cfg(not(target_arch = "wasm32"))]
515	fn commit_touches_pathspecs(
516	    repo: &gix::Repository,
517	    info: &gix::revision::walk::Info<'_>,
518	    commit_obj: &gix::Commit<'_>,
519	    pathspecs: &[PathBuf],
520	) -> Result<bool, VcsError> {
521	    let commit_tree = commit_obj
522	        .tree()
523	        .map_err(|e| VcsError::Git(format!("Failed to load commit tree: {e}")))?;
524	
525	    let parent_tree = match info.parent_ids().next() {
526	        Some(parent_id) => {
527	            let parent_commit = parent_id
528	                .object()
529	                .map_err(|e| VcsError::Git(format!("Failed to load parent commit object: {e}")))?
530	                .into_commit();
531	            parent_commit
532	                .tree()
533	                .map_err(|e| VcsError::Git(format!("Failed to load parent tree: {e}")))?
534	        }
535	        None => repo.empty_tree(),
536	    };
537	
538	    let mut touched = false;
539	    let mut platform = parent_tree
540	        .changes()
541	        .map_err(|e| VcsError::Git(format!("Failed to initialize tree diff: {e}")))?;
542	    // Rewrite (rename/copy) detection needs blob-similarity computation we
543	    // don't otherwise need: pathspec matching only cares about which paths
544	    // changed, not whether they're related across a rename.
545	    platform.options(|o| {
546	        o.track_rewrites(None);
547	    });
548	    // Note: we deliberately always return `Continue` here, never `Break` --
549	    // gix's tree-diff machinery treats an early `Break` as a cancellation
550	    // and surfaces it as an `Err` from `for_each_to_obtain_tree`, which
551	    // would turn "found a match" into a spurious failure.
552	    platform
553	        .for_each_to_obtain_tree(&commit_tree, |change| {
554	            if change_matches_pathspecs(&change, pathspecs) {
555	                touched = true;
556	            }
557	            Ok::<_, std::convert::Infallible>(std::ops::ControlFlow::Continue(()))
558	        })
559	        .map_err(|e| VcsError::Git(format!("Failed to diff commit tree: {e}")))?;
560	
561	    Ok(touched)
562	}
563	
564	#[cfg(not(target_arch = "wasm32"))]
565	fn change_matches_pathspecs(
566	    change: &gix::object::tree::diff::Change<'_, '_, '_>,
567	    pathspecs: &[PathBuf],
568	) -> bool {
569	    use gix::object::tree::diff::Change;
570	    match change {
571	        Change::Addition { location, .. }
572	        | Change::Deletion { location, .. }
573	        | Change::Modification { location, .. } => location_matches(location, pathspecs),
574	        Change::Rewrite {
575	            location,
576	            source_location,
577	            ..
578	        } => location_matches(location, pathspecs) || location_matches(source_location, pathspecs),
579	    }
580	}
581	
582	/// Simple directory/path-prefix pathspec match: a changed path matches a
583	/// pathspec if it's exactly equal to it, or nested underneath it as a
584	/// directory prefix. Does not implement full git pathspec magic syntax.
585	#[cfg(not(target_arch = "wasm32"))]
586	fn location_matches(location: &gix::bstr::BStr, pathspecs: &[PathBuf]) -> bool {
587	    let path_str = String::from_utf8_lossy(location);
588	    let changed_path = Path::new(path_str.as_ref());
589	    pathspecs
590	        .iter()
591	        .any(|spec| changed_path == spec.as_path() || changed_path.starts_with(spec))
592	}
