604	/// Native (`gix`) implementation of [`GitDataSource`].
605	///
606	/// [`Self::commits_since`] is where this crate's `commits_since` ref-not-
607	/// found bug used to live: the old inherent `commits_since(from_ref:
608	/// Option<&str>)` method resolved `from_ref` internally and, if that
609	/// resolution silently failed (bad tag, unborn repo, non-commit object,
610	/// etc.), fell through to walking the *entire* history unbounded instead of
611	/// stopping where the caller asked -- a correctness bug (e.g. it could
612	/// re-surface already-released commits into changelog/severity inference)
613	/// masquerading as graceful degradation. The fix: `since_ref` resolution
614	/// now goes through [`Self::resolve_commit`] and an explicit `Ok(None) =>
615	/// Err(VcsError::RefNotFound)` step below, so an unresolvable *explicit*
616	/// bound is always a surfaced error. `since_ref: None` (no bound requested
617	/// at all) is unaffected and still walks full history, same as before.
618	impl GitDataSource for GitRepository {
619	    fn head_sha(&self) -> Result<CommitSha, VcsError> {
620	        self.head_sha()
621	    }
622	
623	    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
624	        self.list_tags(glob)
625	    }
626	
627	    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
628	        self.resolve_commit(refname)
629	    }
630	
631	    fn commits_since(
632	        &self,
633	        since_ref: Option<&str>,
634	        pathspecs: &[PathBuf],
635	    ) -> Result<Vec<GitCommit>, VcsError> {
636	        let since_sha = since_ref
637	            .map(|r| {
638	                self.resolve_commit(r)?
639	                    .ok_or_else(|| VcsError::RefNotFound {
640	                        ref_name: r.to_string(),
641	                    })
642	            })
643	            .transpose()?;
644	        self.commits_since_with_pathspec(since_sha.as_ref(), pathspecs)
645	    }
646	
647	    fn create_tag(
648	        &self,
649	        name: &str,
650	        target_sha: &CommitSha,
651	        message: Option<&str>,
652	        permit: &ApplyPermit,
653	    ) -> Result<(), VcsError> {
654	        self.create_tag(name, target_sha, message, permit)
655	    }
656	
657	    fn create_floating_major(
658	        &self,
659	        major_name: &str,
660	        target_sha: &CommitSha,
661	        permit: &ApplyPermit,
662	    ) -> Result<(), VcsError> {
663	        self.create_floating_major(major_name, target_sha, permit)
664	    }
665	}
