1187	                .stdout,
1188	        )
1189	        .trim()
1190	        .to_string();
1191	
1192	        // S: the release commit; v1 tag lands here (the "since" lower bound)
1193	        std::fs::write(root.join("s.txt"), "s\n").unwrap();
1194	        run_git(root, &["add", "."]);
1195	        run_git(root, &["commit", "-q", "-m", "chore: S release"]);
1196	        run_git(
