145	    /// A [`CommandRunner`] double that errors on every invocation, proving a
146	    /// code path resolves entirely through native `gix` without ever
147	    /// touching the shell fallback.
148	    struct PoisonedRunner;
149	
150	    impl CommandRunner for PoisonedRunner {
151	        fn run(
152	            &self,
153	            program: &str,
154	            _args: &[&str],
155	            _cwd: &Path,
156	        ) -> Result<CommandOutput, CommandError> {
157	            Err(CommandError::Io {
158	                program: program.to_string(),
159	                message: "poisoned runner: must not shell out to git".to_string(),
160	            })
161	        }
162	    }
