164	    /// Counts invocations and answers `git tag --list` with a canned tag
165	    /// list, standing in for a real `git` binary on the shell fallback path.
166	    struct CountingTagRunner {
167	        calls: AtomicUsize,
168	        tags: Vec<String>,
169	    }
170	
171	    impl CommandRunner for CountingTagRunner {
172	        fn run(
173	            &self,
174	            program: &str,
175	            args: &[&str],
176	            _cwd: &Path,
177	        ) -> Result<CommandOutput, CommandError> {
178	            assert_eq!(program, "git");
179	            assert_eq!(args, ["tag", "--list"]);
180	            self.calls.fetch_add(1, Ordering::SeqCst);
181	            Ok(CommandOutput {
182	                exit_code: Some(0),
183	                stdout: self.tags.join("\n"),
184	                stderr: String::new(),
185	            })
186	        }
187	    }
