1	//! `CommandRunner`-shelled implementation of [`GitDataSource`], consolidated
2	//! from five independently hand-rolled `git`-subprocess fallbacks that used
3	//! to live at each call site (`callisto-graph`'s `changed.rs`, `tags.rs`,
4	//! `commands/tag.rs`, `aggregate.rs`, and `callisto-conventional`'s
5	//! `window.rs`). Every operation here is reachable purely via
6	//! [`callisto_model::CommandRunner`], so it works on every target,
7	//! including `wasm32`, where native `gix` (`GitRepository`) is entirely
8	//! unavailable.
9	//!
10	//! Callers should not construct [`ShellGit`] directly except in tests that
11	//! specifically want to exercise the shell backend in isolation; use
12	//! [`crate::GitAccess::discover`] instead, which selects between this and
13	//! the native backend automatically.
14	
15	use std::path::{Path, PathBuf};
16	
17	use callisto_model::{ApplyPermit, CommandRunner, CommitSha, TagName};
18	
19	use crate::{GitCommit, GitDataSource, VcsError};
20	
21	/// Record separator placed immediately before each commit's fields in
22	/// `git log --format=` output, so a commit message containing `\n` can
23	/// never be mistaken for a record boundary.
24	const RECORD_SEP: char = '\u{1e}';
25	
26	/// Unit separator between a commit's sha and its raw message body in
27	/// `git log --format=` output.
28	const FIELD_SEP: char = '\u{1f}';
29	
30	/// Shells `git` subcommands via a [`CommandRunner`] to implement
31	/// [`GitDataSource`]. See the module docs for the consolidation this
32	/// replaces.
33	pub struct ShellGit<'r> {
34	    runner: &'r dyn CommandRunner,
35	    root: PathBuf,
36	}
37	
38	impl<'r> ShellGit<'r> {
39	    pub fn new(runner: &'r dyn CommandRunner, root: impl Into<PathBuf>) -> Self {
40	        ShellGit {
41	            runner,
42	            root: root.into(),
43	        }
44	    }
45	}
46	
47	/// Compiles `glob` into a [`globset::GlobMatcher`], surfacing a malformed
48	/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
49	/// disable filtering (which would match every tag -- see
50	/// `GitRepository::list_tags`'s own doc comment for why that's a real
51	/// correctness risk for release tagging).
52	fn compile_glob(glob: &str) -> Result<globset::GlobMatcher, VcsError> {
53	    globset::Glob::new(glob)
54	        .map(|g| g.compile_matcher())
55	        .map_err(|e| VcsError::InvalidGlob {
56	            pattern: glob.to_string(),
57	            message: e.to_string(),
58	        })
59	}
60	
61	impl GitDataSource for ShellGit<'_> {
62	    fn head_sha(&self) -> Result<CommitSha, VcsError> {
63	        let output = self.runner.run("git", &["rev-parse", "HEAD"], &self.root)?;
64	        if !output.success() {
65	            return Err(VcsError::Git(format!(
66	                "`git rev-parse HEAD` failed in `{}`: {}",
67	                self.root.display(),
68	                output.stderr
69	            )));
70	        }
71	        let sha_str = output.stdout_trimmed();
72	        CommitSha::parse(sha_str)
73	            .map_err(|e| VcsError::Git(format!("could not parse HEAD SHA `{sha_str}`: {e}")))
74	    }
75	
76	    /// Always fetches the *full, unfiltered* tag list via `git tag --list`
77	    /// and applies `glob` (if any) locally with `globset` -- deliberately
78	    /// never delegates filtering to `git tag --list <pattern>`'s own
79	    /// (different) glob dialect. This is what guarantees byte-identical
80	    /// tag selection between this backend and the native `gix` path
81	    /// (`GitRepository::list_tags`, which also filters with `globset`)
82	    /// regardless of which one a caller ends up using.
83	    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
84	        let output = self.runner.run("git", &["tag", "--list"], &self.root)?;
85	        let all = output.stdout_lines().map(|s| s.to_string());
86	
87	        let matcher = glob.map(compile_glob).transpose()?;
88	
89	        Ok(all
90	            .filter(|t| matcher.as_ref().is_none_or(|m| m.is_match(t)))
91	            .map(TagName)
92	            .collect())
93	    }
94	
95	    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
96	        let rev = format!("{refname}^{{commit}}");
97	        let output = self.runner.run(
98	            "git",
99	            &["rev-parse", "--verify", "--quiet", &rev],
100	            &self.root,
101	        )?;
102	
103	        if !output.success() {
104	            return Ok(None);
105	        }
106	        let sha_str = output.stdout_trimmed();
107	        if sha_str.is_empty() {
108	            return Ok(None);
109	        }
110	        Ok(CommitSha::parse(sha_str).ok())
111	    }
112	
113	    /// Shells `git log --no-merges --format=<RECORD_SEP>%H<FIELD_SEP>%B
114	    /// <range> [-- <pathspecs>]`, matching the native path's shape
115	    /// field-for-field: `--no-merges` excludes merge commits exactly like
116	    /// `GitRepository::commits_since_with_pathspec`'s parent-count skip;
117	    /// `<since>..HEAD` (or bare `HEAD` for no bound) gives the same
118	    /// exclusive-lower-bound revision range as the revwalk's stop-at-
119	    /// `since` logic; and the trailing `-- <pathspecs>` reproduces `git
120	    /// log`'s own pathspec-prefix filtering.
121	    ///
122	    /// Deliberately does *not* pre-resolve `since_ref` via a separate
123	    /// `rev-parse` round-trip: an unresolvable `since_ref` already makes
124	    /// `git log <since_ref>..HEAD` itself fail (non-zero exit), which is
125	    /// surfaced below as `Err` exactly like any other `git log` failure --
126	    /// one shell call either way.
127	    fn commits_since(
128	        &self,
129	        since_ref: Option<&str>,
130	        pathspecs: &[PathBuf],
131	    ) -> Result<Vec<GitCommit>, VcsError> {
132	        let mut args: Vec<String> = vec![
133	            "log".to_string(),
134	            "--no-merges".to_string(),
135	            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
136	        ];
137	
138	        match since_ref {
139	            Some(r) => args.push(format!("{r}..HEAD")),
140	            None => args.push("HEAD".to_string()),
141	        }
142	
143	        if !pathspecs.is_empty() {
144	            args.push("--".to_string());
145	            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
146	        }
147	
148	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
149	        let output = self.runner.run("git", &arg_refs, &self.root)?;
150	
151	        if !output.success() {
152	            return Err(VcsError::Git(format!(
153	                "`git log` failed in `{}`: {}",
154	                self.root.display(),
155	                output.stderr
156	            )));
157	        }
158	
159	        parse_git_log_output(&output.stdout, &self.root)
160	    }
161	
162	    fn create_tag(
163	        &self,
164	        name: &str,
165	        target_sha: &CommitSha,
166	        message: Option<&str>,
167	        _permit: &ApplyPermit,
168	    ) -> Result<(), VcsError> {
169	        // `--` marks the end of option parsing so `name` (validated
170	        // upstream by `is_valid_git_ref_name`, but defended here too) can
171	        // never be misread as a `git tag` flag even if it started with `-`.
172	        let output = match message {
173	            Some(msg) => self.runner.run(
174	                "git",
175	                &["tag", "-a", "-m", msg, "--", name, target_sha.as_str()],
176	                &self.root,
177	            )?,
178	            None => {
179	                self.runner
180	                    .run("git", &["tag", "--", name, target_sha.as_str()], &self.root)?
181	            }
182	        };
183	        if !output.success() {
184	            return Err(VcsError::Git(format!(
185	                "`git tag` failed in `{}`: {}",
186	                self.root.display(),
187	                output.stderr
188	            )));
189	        }
190	        Ok(())
191	    }
192	
193	    fn create_floating_major(
194	        &self,
195	        major_name: &str,
196	        target_sha: &CommitSha,
197	        _permit: &ApplyPermit,
198	    ) -> Result<(), VcsError> {
199	        let output = self.runner.run(
200	            "git",
201	            &["tag", "-f", "--", major_name, target_sha.as_str()],
202	            &self.root,
203	        )?;
204	        if !output.success() {
205	            return Err(VcsError::Git(format!(
206	                "`git tag -f` failed in `{}`: {}",
207	                self.root.display(),
208	                output.stderr
209	            )));
210	        }
211	        Ok(())
212	    }
213	}
