113	    /// Shells `git log --no-merges --format=<RECORD_SEP>%H<FIELD_SEP>%B
114	    /// <range> [-- <pathspecs>]`, matching the native path's shape
115	    /// field-for-field: `--no-merges` excludes merge commits exactly like
116	    /// `GitRepository::commits_since_with_pathspec`'s parent-count skip;
117	    /// `<since>..HEAD` (or bare `HEAD` for no bound) gives the same
118	    /// exclusive-lower-bound revision range as the revwalk's stop-at-
119	    /// `since` logic; and the trailing `-- <pathspecs>` reproduces `git
120	    /// log`'s own pathspec-prefix filtering.
121	    ///
122	    /// Deliberately does *not* pre-resolve `since_ref` via a separate
123	    /// `rev-parse` round-trip: an unresolvable `since_ref` already makes
124	    /// `git log <since_ref>..HEAD` itself fail (non-zero exit), which is
125	    /// surfaced below as `Err` exactly like any other `git log` failure --
126	    /// one shell call either way.
127	    fn commits_since(
128	        &self,
129	        since_ref: Option<&str>,
130	        pathspecs: &[PathBuf],
131	    ) -> Result<Vec<GitCommit>, VcsError> {
132	        let mut args: Vec<String> = vec![
133	            "log".to_string(),
134	            "--no-merges".to_string(),
135	            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
136	        ];
137	
138	        match since_ref {
139	            Some(r) => args.push(format!("{r}..HEAD")),
140	            None => args.push("HEAD".to_string()),
141	        }
142	
143	        if !pathspecs.is_empty() {
144	            args.push("--".to_string());
145	            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
146	        }
147	
148	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
149	        let output = self.runner.run("git", &arg_refs, &self.root)?;
150	
151	        if !output.success() {
152	            return Err(VcsError::Git(format!(
153	                "`git log` failed in `{}`: {}",
154	                self.root.display(),
155	                output.stderr
156	            )));
157	        }
158	
159	        parse_git_log_output(&output.stdout, &self.root)
160	    }
