215	/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
216	/// produced by [`ShellGit::commits_since`] into [`GitCommit`]s, splitting
217	/// each raw message on its first blank line into `summary`/`body` --
218	/// mirroring how `gix`'s own commit-message parsing (used by
219	/// `GitRepository::commits_since_with_pathspec`) splits title from body,
220	/// so both backends hand callers the same shape.
221	fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
222	    let mut commits = Vec::new();
223	
224	    for record in stdout.split(RECORD_SEP) {
225	        // `tformat:`-style `--format=` output (the default when the format
226	        // string doesn't start with `format:`/`tformat:`) appends a
227	        // trailing newline after every entry; strip it rather than the
228	        // message's own content.
229	        let record = record.trim_end_matches('\n');
230	        if record.is_empty() {
231	            continue;
232	        }
233	
234	        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
235	            return Err(VcsError::Git(format!(
236	                "could not parse `git log` output in `{}` into commit records: expected a \
237	                 `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
238	                cwd.display()
239	            )));
240	        };
241	
242	        let sha = CommitSha::parse(sha_str).map_err(|e| {
243	            VcsError::Git(format!(
244	                "could not parse `git log` output in `{}`: invalid commit SHA `{sha_str}`: {e}",
245	                cwd.display()
246	            ))
247	        })?;
248	
249	        let message = message.replace("\r\n", "\n");
250	        let (summary, body) = match message.split_once("\n\n") {
251	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
252	            None => (message.trim_end().to_string(), None),
253	        };
254	
255	        commits.push(GitCommit { sha, summary, body });
256	    }
257	
258	    Ok(commits)
259	}
