400	/// Reads `package.json` at `abs_path` and returns `ManifestRole::Platform`
401	/// when the manifest declares both `os` and `cpu` constraint arrays (the napi
402	/// platform-package convention). Returns `ManifestRole::Canonical` for all
403	/// other npm packages and on any read/parse failure.
404	///
405	/// Note: this performs a second `fs::read` on each npm `package.json` because
406	/// the `manifest_cache` stores `Arc<dyn Manifest>` (which does not expose raw
407	/// JSON fields like `os`/`cpu`) rather than a raw `serde_json::Value`. Fixing
408	/// the redundancy would require a `Manifest::npm_role()` extension method in
409	/// the `callisto-manifests` crate.
410	fn detect_npm_role(abs_path: &Path) -> ManifestRole {
411	    let Ok(bytes) = std::fs::read(abs_path) else {
412	        return ManifestRole::Canonical;
413	    };
414	    let Ok(Value::Object(map)) = serde_json::from_slice(&bytes) else {
415	        return ManifestRole::Canonical;
416	    };
417	
418	    let has_os = map
419	        .get("os")
420	        .and_then(|v| v.as_array())
421	        .is_some_and(|a| !a.is_empty());
422	    let has_cpu = map
423	        .get("cpu")
424	        .and_then(|v| v.as_array())
425	        .is_some_and(|a| !a.is_empty());
426	
427	    if !has_os || !has_cpu {
428	        return ManifestRole::Canonical;
429	    }
430	
431	    let Some(platform) = map
432	        .get("os")
433	        .and_then(|v| v.as_array())
434	        .and_then(|a| a.first())
435	        .and_then(|v| v.as_str())
436	        .map(str::to_string)
437	    else {
438	        return ManifestRole::Canonical;
439	    };
440	
441	    let Some(arch) = map
442	        .get("cpu")
443	        .and_then(|v| v.as_array())
444	        .and_then(|a| a.first())
445	        .and_then(|v| v.as_str())
446	        .map(str::to_string)
447	    else {
448	        return ManifestRole::Canonical;
449	    };
450	
451	    // npm's standard `os`/`cpu` manifest fields have no libc/ABI concept at
452	    // all, so a real disk-discovered Linux napi platform package always
453	    // produced `abi: None` here -- but `napi.rs::role_to_triple`'s Linux
454	    // match arms all require a concrete ABI, meaning such a package could
455	    // never resolve to its triple. napi-rs's own package-generation
456	    // convention encodes the ABI in the package *name*'s suffix instead
457	    // (e.g. "@scope/pkg-linux-x64-gnu"), so infer it from there when the
458	    // platform is linux.
459	    let abi = if platform == "linux" {
460	        map.get("name")
461	            .and_then(|v| v.as_str())
462	            .and_then(napi_linux_abi_from_package_name)
463	    } else {
464	        None
465	    };
466	
467	    ManifestRole::Platform {
468	        platform,
469	        arch,

        _ => u8::MAX,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Real disk-discovered Linux napi platform packages always have
    /// `abi: None` from `detect_npm_role` (npm's standard `os`/`cpu`
    /// manifest fields have no libc/ABI concept), but `napi.rs::role_to_triple`'s
    /// Linux match arms all require `Some("gnu")`/`Some("musl")`/
    /// `Some("gnueabihf")` -- so before this fix, `role_to_triple` could
    /// never resolve a real, disk-discovered Linux platform package to its
    /// triple, and `napi_drift` would spuriously report it as a
    /// declared-but-missing group member even though it's genuinely present
    /// on disk with the correct name.
    #[test]
    fn detect_npm_role_infers_linux_gnu_abi_from_package_name_suffix() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("package.json");
        std::fs::write(
            &path,
            r#"{"name":"@scope/my-lib-linux-x64-gnu","version":"1.0.0","os":["linux"],"cpu":["x64"]}"#,
        )
        .unwrap();

        let role = detect_npm_role(&path);

        assert_eq!(
            crate::napi::role_to_triple(&role).as_deref(),
            Some("x86_64-unknown-linux-gnu"),
            "expected a resolvable triple, got role: {role:?}"
        );
    }

    #[test]
    fn detect_npm_role_infers_linux_musl_abi_from_package_name_suffix() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("package.json");
        std::fs::write(
            &path,
            r#"{"name":"@scope/my-lib-linux-arm64-musl","version":"1.0.0","os":["linux"],"cpu":["arm64"]}"#,
        )
        .unwrap();

        let role = detect_npm_role(&path);

        assert_eq!(
            crate::napi::role_to_triple(&role).as_deref(),
            Some("aarch64-unknown-linux-musl"),
            "expected a resolvable triple, got role: {role:?}"
        );
    }

    #[test]
    fn detect_npm_role_infers_linux_gnueabihf_abi_from_package_name_suffix() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("package.json");
        std::fs::write(
            &path,
            r#"{"name":"@scope/my-lib-linux-arm-gnueabihf","version":"1.0.0","os":["linux"],"cpu":["arm"]}"#,
        )
        .unwrap();

        let role = detect_npm_role(&path);

        assert_eq!(
            crate::napi::role_to_triple(&role).as_deref(),
            Some("armv7-unknown-linux-gnueabihf"),
            "expected a resolvable triple, got role: {role:?}"
        );
    }

    /// Non-Linux platforms have no ABI concept in `role_to_triple`'s table
    /// (`abi` is always `None` there) -- must not be affected by the
    /// name-suffix inference at all.
    #[test]
    fn detect_npm_role_does_not_infer_abi_for_non_linux_platforms() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("package.json");
        std::fs::write(
            &path,
            r#"{"name":"@scope/my-lib-darwin-arm64-gnu","version":"1.0.0","os":["darwin"],"cpu":["arm64"]}"#,
        )
        .unwrap();

        let role = detect_npm_role(&path);

        assert_eq!(
            role,
            ManifestRole::Platform {
                platform: "darwin".to_string(),
                arch: "arm64".to_string(),
                abi: None,
            }
        );
    }

    /// A Linux platform package whose name has no recognized ABI suffix at
    /// all stays `abi: None` -- this function infers when it can, it
    /// doesn't invent an ABI that isn't actually signaled anywhere.
    #[test]
    fn detect_npm_role_leaves_abi_none_when_linux_name_has_no_recognized_suffix() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("package.json");
        std::fs::write(
            &path,
            r#"{"name":"@scope/my-lib-linux-x64","version":"1.0.0","os":["linux"],"cpu":["x64"]}"#,
        )
        .unwrap();

        let role = detect_npm_role(&path);

        assert_eq!(
            role,
            ManifestRole::Platform {
                platform: "linux".to_string(),
                arch: "x64".to_string(),
                abi: None,
            }
        );
    }
}

