    total_claims_checked: survey.total_claims_checked,
    confirmed_count: survey.confirmed_count,
    verified_gaps: verified.filter(Boolean),
  }))
)

const allConfirmedGaps = results
  .filter(Boolean)
  .flatMap(r => r.verified_gaps)
  .filter(g => g.verdict && g.verdict.confirmed)

const totalClaims = results.filter(Boolean).reduce((sum, r) => sum + (r.total_claims_checked || 0), 0)
const totalConfirmed = results.filter(Boolean).reduce((sum, r) => sum + (r.confirmed_count || 0), 0)

log(`Audit complete: ${totalClaims} claims checked across ${UNITS.length} units, ${allConfirmedGaps.length} gaps confirmed after adversarial verification.`)

phase('Synthesize')
const report = await agent(
  `You are writing the final report for a full spec-conformance audit of the Callisto Rust workspace. Below is the complete list of CONFIRMED gaps (already adversarially verified -- each one independently re-checked against real code and spec, so treat these as real) found across all crates.

Total claims checked across the whole workspace: ${totalClaims}. Total confirmed correct: ${totalConfirmed}. Total confirmed gaps: ${allConfirmedGaps.length}.

Confirmed gaps (JSON):
${JSON.stringify(allConfirmedGaps, null, 2)}

Write a clear, well-organized markdown report for a technical audience (the workspace's maintainer). Structure:
1. A short executive summary (2-4 sentences): overall health, headline numbers, the most important 1-3 findings.
2. Findings grouped by severity (critical first, then high, medium, low), each with: crate, one-line description, spec citation, expected vs actual, evidence (file:line), and severity.
3. A short closing section noting the audit's own scope/limits (which crates/sections were covered, and that this covered docs/00-design.md + docs/01-spec.md against current code, not runtime/production behavior).

If allConfirmedGaps is empty, say so clearly and positively -- don't manufacture findings. Return only the markdown report text, no preamble.`,
  { label: 'synthesize-report', phase: 'Synthesize', effort: 'high' }
)

return { totalClaims, totalConfirmed, gapsFound: allConfirmedGaps.length, allConfirmedGaps, report }

