export const meta = {
  name: 'callisto-runtime-perf-audit',
  description: 'Runtime reproduction of static findings, new runtime-issue sweep, and performance audit',
  phases: [
    { title: 'Runtime Repro & Sweep', detail: 'per-crate agents actually run the compiled callisto binary against constructed scenarios' },
    { title: 'Performance Audit', detail: 'synthetic-scale timing + hot-path redundancy checks' },
    { title: 'Verify Findings', detail: 'adversarial refutation on Opus for new issues, perf findings, and any refuted static claims' },
    { title: 'Synthesize', detail: 'final combined report' },
  ],
}

const REPRO_SCHEMA = {
  type: 'object',
  properties: {
    runtime_checks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          finding_description: { type: 'string' },
          status: { type: 'string', enum: ['reproduced', 'not_reproducible', 'not_applicable'] },
          command_run: { type: 'string' },
          actual_output: { type: 'string' },
          notes: { type: 'string' },
        },
        required: ['finding_description', 'status', 'notes'],
      },
    },
    new_issues: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          description: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          category: { type: 'string', enum: ['correctness', 'crash', 'output-contract', 'usability', 'other'] },
          evidence: { type: 'string' },
        },
        required: ['description', 'severity', 'category', 'evidence'],
      },
    },
  },
  required: ['runtime_checks', 'new_issues'],
}

const PERF_SCHEMA = {
  type: 'object',
  properties: {
    perf_findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          description: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          category: { type: 'string', enum: ['redundant-io', 'superlinear-scaling', 'other'] },
          evidence: { type: 'string' },
        },
        required: ['description', 'severity', 'category', 'evidence'],
      },
    },
  },
  required: ['perf_findings'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    confirmed: { type: 'boolean' },
    reasoning: { type: 'string' },
  },
  required: ['confirmed', 'reasoning'],
}

const findings = args && args.findings ? args.findings : []
const byCrate = {}
for (const f of findings) {
  byCrate[f.crate] = byCrate[f.crate] || []
  byCrate[f.crate].push(f)
}

const REPRO_UNITS = Object.keys(byCrate).map(crate => ({ crate, findings: byCrate[crate] }))

function reproPrompt(unit) {
  const findingsText = unit.findings.map((f, i) =>
    `${i + 1}. ${f.description}\n   Spec: ${f.spec_citation}\n   Expected: ${f.expected}\n   Static finding's actual: ${f.actual}\n   Evidence cited: ${f.evidence}`
  ).join('\n\n')

  return `You are runtime-testing the Callisto Rust workspace at the current working directory (/Users/gabe/Projects/callisto). A prior STATIC audit (reading code, no execution) found the findings below for unit "${unit.crate}". Your job is to actually RUN the software and see what really happens -- not just re-read the code.

IMPORTANT SAFETY RULE: never modify, commit, or push anything in the real working directory (/Users/gabe/Projects/callisto) itself. Build the project there (cargo build) if needed, but all test scenarios (git repos, workspaces, fixtures you construct to exercise the code) MUST live under a fresh temp directory (e.g. mktemp -d), never inside the real repo. You have Bash -- use it to mkdir/git init/write files under a tmp dir, then run the compiled callisto binary or targeted cargo tests against that tmp dir.

Findings to runtime-test for this unit:

${findingsText}

For EACH finding above, try to build the smallest real scenario that would exercise it, using the actual code (compile with \`cargo build -p callisto-cli\` or \`cargo build --workspace\`, then run the real \`callisto\` binary -- e.g. \`./target/debug/callisto version --format json\` -- against a constructed tmp workspace; or write and run a small targeted \`cargo test\`/\`cargo run --example\` if that's a more direct way to exercise the specific function). Report status:
- "reproduced" if you got the real system to actually exhibit the described gap/bug, with the exact command(s) you ran and the real output as evidence.
- "not_reproducible" if you tried and the real runtime behavior does NOT match what the static finding claims (e.g. it turns out to work correctly, or fails differently) -- explain exactly what you observed instead.
- "not_applicable" for findings that are pure code-facts not really susceptible to a runtime repro (e.g. "this dependency is declared but unused", "this struct is missing a field") -- for these, just note that a static read already settles it and no separate runtime repro adds information; don't force a fake repro.

Prioritize getting through all the findings with a real attempt over spending unlimited time perfecting any one repro -- if something is hard to set up in a few minutes, note what you tried and move on.

Additionally, while you have this part of the system running for real: proactively look for OTHER runtime-only problems you notice that were NOT in the static findings list above -- panics, unexpected non-zero/zero exit codes, JSON output that doesn't match what any doc claims, confusing or wrong error messages, hangs, or anything that surprised you. Report these as new_issues with your own severity judgment and category.`
}

const PERF_UNITS = [
  {
    key: 'graph-scale',
    prompt: `You are performance-testing the Callisto Rust workspace at the current working directory (/Users/gabe/Projects/callisto), focused on callisto-graph (workspace discovery, config resolution, cascade, aggregation) at scale.

SAFETY: never modify the real working directory itself. Build synthetic test workspaces only under a fresh tmp dir (mktemp -d).

Build \`cargo build --release -p callisto-cli\` (release mode, for realistic timing). Then construct THREE synthetic git-repo workspaces of increasing size under tmp dirs: ~10 packages, ~75 packages, ~250 packages (mix of Cargo crates and npm packages is ideal but plain Cargo-only is fine if faster to script; give each package a trivial Cargo.toml/package.json and a git-initialized repo with a few commits and release tags so tag/commit-history operations have real data to walk). Time (using \`time\` or manual timestamps) running \`callisto status\`, \`callisto version --dry-run\`, and \`callisto matrix\` against each of the three sizes.

Look specifically for: (a) superlinear scaling -- does 25x more packages cost dramatically more than 25x the time, suggesting an O(n^2) or worse pattern rather than roughly-linear discovery/aggregation cost; (b) redundant work you can infer from timing -- e.g. does re-running the identical command twice in a row cost the same both times (expected, no caching needed) or does one single invocation seem to redo expensive git/filesystem work multiple times (check by grepping the source for repeated GitAccess::discover or repeated manifest-open patterns per command, cross-referencing against what you observe in timing). This crate has a known history this session of exactly this bug class (redundant GitAccess::discover calls within one command) already partially fixed -- look for any remaining instances or newly reintroduced ones.

Report perf_findings for anything concerning, with the actual timing numbers and commands as evidence. If everything scales reasonably and you find nothing concerning, say so plainly rather than manufacturing a finding.`
  },
  {
    key: 'manifests-io',
    prompt: `You are performance-testing crates/callisto-manifests (the Cargo.toml/package.json/pyproject.toml editors) in the Callisto Rust workspace at the current working directory (/Users/gabe/Projects/callisto).

SAFETY: never modify the real working directory itself. Build synthetic test scenarios only under a fresh tmp dir.

Read the actual manifest-open/write/persist code paths (crates/callisto-manifests/src/cargo.rs, npm.rs, python.rs, lib.rs). Specifically check: does opening or writing a manifest ever re-read/re-parse the same file more than once within a single logical operation (e.g. a version bump plus several dependency rewrites targeting the same file)? Is there redundant I/O when many packages in one workspace share a manifest file (e.g. a Cargo workspace root)? Build a small real repro (tmp dir, a Cargo workspace with several members) and run the real callisto binary's \`version\`/\`publish --dry-run\` against it, instrumenting or reasoning from the code to count actual open/parse calls per file.

Report perf_findings for any redundant-I/O pattern found, with file:line evidence and, where feasible, an actual reproduction command. If nothing concerning is found, say so.`
  },
  {
    key: 'vcs-git-ops',
    prompt: `You are performance-testing crates/callisto-vcs (the git access layer: GitAccess, GitRepository/gix, ShellGit) in the Callisto Rust workspace at the current working directory (/Users/gabe/Projects/callisto).

SAFETY: never modify the real working directory itself. Build synthetic test git repos only under a fresh tmp dir.

Build a synthetic git repo under a tmp dir with ~200 tags and ~500 commits (a small script loop is fine -- doesn't need real content, empty commits are fine: \`git commit --allow-empty\`). Build \`cargo build --release -p callisto-cli\`. Time \`callisto status\` and \`callisto version --dry-run\` against this repo, and separately check (by reading the code and/or by adding temporary eprintln instrumentation in a SCRATCH COPY if needed, never editing the real repo's committed files) whether tag listing / commit walking gets redundantly re-fetched within one command invocation, and whether the native gix path vs the CommandRunner-shell-fallback path are both efficient at this scale (200+ tags, 500+ commits).

Report perf_findings with real timing numbers and evidence. If it performs fine at this scale, say so.`
  },
  {
    key: 'cli-startup',
    prompt: `You are performance-testing crates/callisto-cli's startup and per-command overhead in the Callisto Rust workspace at the current working directory (/Users/gabe/Projects/callisto).

SAFETY: never modify the real working directory itself. Build synthetic test scenarios only under a fresh tmp dir.

Build \`cargo build --release -p callisto-cli\`. Time a bare \`callisto --help\` and a trivial \`callisto status\` against a tiny 1-package tmp workspace, run several times, to establish baseline process/startup overhead (workspace discovery, config load, etc. before any real work happens). Then read crates/callisto-cli/src/main.rs and crates/callisto-cli/src/workspace.rs's load_workspace to check whether any command handler does redundant work at startup (e.g. discovering the workspace root, loading config, or building the dependency graph more than once per invocation).

Report perf_findings for any real overhead found, with timing evidence. If startup is fast and lean, say so.`
  },
]

phase('Runtime Repro & Sweep')
const reproResults = await pipeline(
  REPRO_UNITS,
  unit => agent(reproPrompt(unit), {
    label: `repro:${unit.crate}`,
    phase: 'Runtime Repro & Sweep',
    schema: REPRO_SCHEMA,
    agentType: 'bug-hunter',
  })
)

phase('Performance Audit')
const perfResults = await pipeline(
  PERF_UNITS,
  unit => agent(unit.prompt, {
    label: `perf:${unit.key}`,
    phase: 'Performance Audit',
    schema: PERF_SCHEMA,
    agentType: 'bug-hunter',
  })
)

log(`Repro+sweep done across ${REPRO_UNITS.length} units; perf audit done across ${PERF_UNITS.length} units. Moving to adversarial verification (Opus).`)

phase('Verify Findings')

const toVerify = []
reproResults.forEach((r, i) => {
  if (!r) return
  const unit = REPRO_UNITS[i]
  ;(r.new_issues || []).forEach(issue => toVerify.push({ kind: 'new_issue', source: unit.crate, item: issue }))
  ;(r.runtime_checks || []).filter(c => c.status === 'not_reproducible').forEach(chk =>
    toVerify.push({ kind: 'refuted_static_finding', source: unit.crate, item: chk })
  )
})
perfResults.forEach((r, i) => {
  if (!r) return
  const unit = PERF_UNITS[i]
  ;(r.perf_findings || []).forEach(f => toVerify.push({ kind: 'perf_finding', source: unit.key, item: f }))
})

function verifyPrompt(entry) {
  if (entry.kind === 'new_issue') {
    return `You are adversarially verifying a NEW runtime issue found during a live runtime audit of the Callisto Rust workspace at the current working directory (this was found while runtime-testing ${entry.source}, not from the earlier static audit). Default assumption: WRONG until you independently confirm it.

Claimed issue: ${entry.item.description}
Severity claimed: ${entry.item.severity}
Category: ${entry.item.category}
Evidence: ${entry.item.evidence}

Independently reproduce this yourself if at all possible (build a fresh tmp scenario, run the real binary, see what actually happens -- never modify the real working directory). Read any cited code directly. Confirm only if you get the same result yourself or the code unambiguously supports the claim.`
  }
  if (entry.kind === 'refuted_static_finding') {
    return `A runtime-repro pass during a live audit of the Callisto Rust workspace tried to reproduce an EARLIER, already-adversarially-confirmed STATIC finding at runtime and reported it as NOT reproducible -- meaning the runtime attempt suggests the static finding might be wrong, or the repro attempt itself was flawed. You are the tie-breaker: figure out which is true.

Original static finding: ${entry.item.finding_description}
Runtime attempt's command: ${entry.item.command_run || '(none recorded)'}
Runtime attempt's actual output: ${entry.item.actual_output || '(none recorded)'}
Runtime attempt's notes on why it didn't reproduce: ${entry.item.notes}

Read the actual code yourself. If useful, attempt your own independent repro (never modify the real working directory; tmp dirs only). Decide: was the ORIGINAL static finding correct (the runtime repro attempt was flawed/didn't set up the right conditions), or was the runtime attempt right that the static finding doesn't actually hold up? Set confirmed:true if you conclude the DISCREPANCY itself is real and worth flagging in the report (i.e. either the static finding was wrong, or there's a genuine reproducibility gap worth noting) -- reasoning should state clearly which side you landed on and why.`
  }
  return `You are adversarially verifying a claimed PERFORMANCE issue found during a live runtime/perf audit of the Callisto Rust workspace at the current working directory (found while perf-testing ${entry.source}). Default assumption: WRONG or overstated until independently confirmed.

Claimed finding: ${entry.item.description}
Severity claimed: ${entry.item.severity}
Category: ${entry.item.category}
Evidence: ${entry.item.evidence}

Read the cited code yourself. If the evidence includes timing numbers, sanity-check whether the claimed conclusion (e.g. "superlinear", "redundant") is actually supported by those numbers rather than noise, and independently re-run the timing yourself if feasible (tmp dirs only, never modify the real working directory). Confirm only if you're independently convinced this is a real, non-trivial performance problem.`
}

const verified = await parallel(
  toVerify.map(entry => () =>
    agent(verifyPrompt(entry), {
      label: `verify:${entry.kind}:${entry.source}`,
      phase: 'Verify Findings',
      schema: VERIFY_SCHEMA,
      agentType: 'bug-hunter',
      model: 'opus',
    }).then(v => ({ ...entry, verdict: v }))
  )
)

const confirmedNewIssues = verified.filter(Boolean).filter(v => v.kind === 'new_issue' && v.verdict && v.verdict.confirmed)
const confirmedDiscrepancies = verified.filter(Boolean).filter(v => v.kind === 'refuted_static_finding' && v.verdict && v.verdict.confirmed)
