65	    pub fn matches_in_ecosystems(&self, name: &str, ecosystems: &[Ecosystem]) -> bool {
66	        if let Some(want) = self.ecosystem {
67	            if !ecosystems.contains(&want) {
68	                return false;
69	            }
70	        }
71	        self.matcher.is_match(name)
72	    }
73	
74	    pub fn as_str(&self) -> &str {
75	        &self.raw
76	    }
77	}
