    fs::create_dir_all(root.join("crates/my-native-lib")).unwrap();
    fs::write(
        root.join("crates/my-native-lib/Cargo.toml"),
        "[package]\nname = \"my-native-lib\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
