    /// `--tag snapshot` produces. `severity` is unconditionally `Patch` for a snapshot run.
    pub bumps: Vec<BumpRecord>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub diagnostics: Vec<Diagnostic>,
