8	/// Prepend a rendered changelog entry for `display_name` to the changelog file
9	/// at `changelog_path` (relative to `root`).
10	///
11	/// # Concurrency
12	///
13	/// This function is **not safe for concurrent calls on the same `path`**. It
14	/// reads the existing file contents and then writes atomically, but a second
15	/// concurrent call for the same changelog file would read stale content between
16	/// those two points. Callers must ensure sequential access per changelog file.
17	/// If the codebase ever moves to parallel `apply`, add a per-path lock or
18	/// channel before removing this note.
19	pub fn prepend(
20	    root: &Path,
21	    changelog_path: &Path,
22	    display_name: &str,
23	    rendered: &str,
24	    permit: &ApplyPermit,
25	) -> Result<(), ChangelogError> {
26	    let full_path = root.join(changelog_path);
27	    if let Some(parent) = full_path.parent() {
28	        fs::create_dir_all(parent).map_err(|e| ChangelogError::WriteFailed {
29	            path: changelog_path.to_path_buf(),
30	            message: e.to_string(),
31	        })?;
32	    }
33	
34	    let existing = if full_path.exists() {
35	        fs::read_to_string(&full_path).map_err(|e| ChangelogError::ReadFailed {
36	            path: changelog_path.to_path_buf(),
37	            message: e.to_string(),
38	        })?
39	    } else {
40	        format!("# {display_name}\n\n")
41	    };
42	
43	    // Normalise CRLF → LF so the prefix patterns always match, then restore
44	    // the original line endings on the way out if the file used CRLF.
45	    let had_crlf = existing.contains("\r\n");
46	    let normalised = if had_crlf {
47	        existing.replace("\r\n", "\n")
48	    } else {
49	        existing.clone()
50	    };
51	
52	    // Bug 8 guard: if the version heading we are about to insert already exists
53	    // in the file, skip the write entirely (idempotent behaviour). The heading
54	    // is the first line of `rendered` (e.g. "## 1.0.0").
55	    let version_heading = rendered.lines().next().unwrap_or("").trim();
56	    if !version_heading.is_empty() && normalised.lines().any(|l| l.trim() == version_heading) {
57	        return Ok(());
58	    }
59	
60	    let mut new_content = String::new();
61	    if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n\n")) {
62	        new_content.push_str(&format!("# {display_name}\n\n"));
63	        new_content.push_str(rendered);
64	        if !rendered.ends_with('\n') {
65	            new_content.push('\n');
66	        }
67	        new_content.push('\n');
68	        new_content.push_str(rest);
69	    } else if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n")) {
70	        new_content.push_str(&format!("# {display_name}\n\n"));
71	        new_content.push_str(rendered);
72	        if !rendered.ends_with('\n') {
73	            new_content.push('\n');
74	        }
75	        new_content.push('\n');
76	        new_content.push_str(rest);
77	    } else {
78	        // The existing header didn't match display_name (e.g. casing change,
79	        // HTML anchor, or package rename). Always emit the correct H1 first so
80	        // the output is well-formed: H1 → new entry → existing body.
81	        new_content.push_str(&format!("# {display_name}\n\n"));
82	        new_content.push_str(rendered);
83	        if !rendered.ends_with('\n') {
84	            new_content.push('\n');
85	        }
86	        new_content.push('\n');
87	        new_content.push_str(&normalised);
88	    }
89	
90	    if had_crlf {
91	        new_content = new_content.replace('\n', "\r\n");
92	    }
93	
94	    callisto_model::atomic::atomic_write(&full_path, &new_content, permit).map_err(|e| {
95	        ChangelogError::WriteFailed {
96	            path: changelog_path.to_path_buf(),
97	            message: e.to_string(),
98	        }
99	    })
100	}
