102	pub fn extract_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
103	    let target_heading = format!("## {}", version.render());
104	    let mut start_byte = None;
105	
106	    let mut offset = 0;
107	    for line in changelog.split_inclusive('\n') {
108	        let trimmed = line.trim_end();
109	        if trimmed == target_heading {
110	            start_byte = Some(offset + line.len());
111	            break;
112	        }
113	        offset += line.len();
114	    }
115	
116	    let start = start_byte?;
117	    let slice_after = &changelog[start.min(changelog.len())..];
118	
119	    let mut end = slice_after.len();
120	    let mut line_offset = 0;
121	
122	    for line in slice_after.split_inclusive('\n') {
123	        let trimmed = line.trim_start();
124	        if line_offset > 0 && (trimmed.starts_with("## ") || trimmed.starts_with("# ")) {
125	            end = line_offset;
126	            break;
127	        }
128	        line_offset += line.len();
129	    }
130	
131	    let raw_section = slice_after[..end.min(slice_after.len())].trim();
132	    if raw_section.is_empty() {
133	        None
134	    } else {
135	        Some(raw_section)
136	    }
137	}
