7	pub fn toposort_impl<F>(
8	    subset: &HashSet<PackageId>,
9	    all_packages: &[PackageId],
10	    outgoing_edges: F,
11	) -> Result<Vec<PackageId>, GraphError>
12	where
13	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
14	{
15	    let members: BTreeSet<PackageId> = subset.iter().cloned().collect();
16	    // Build a HashSet once so validation is O(N) rather than O(N²) slice scans.
17	    let all_set: std::collections::HashSet<&PackageId> = all_packages.iter().collect();
18	    for id in &members {
19	        if !all_set.contains(id) {
20	            return Err(GraphError::UnknownPackage { id: id.clone() });
21	        }
22	    }
23	
24	    let mut in_degree: BTreeMap<PackageId, usize> = BTreeMap::new();
25	    let mut adj: BTreeMap<PackageId, Vec<PackageId>> = BTreeMap::new();
26	
27	    for u in &members {
28	        in_degree.insert(u.clone(), 0);
29	        adj.insert(u.clone(), Vec::new());
30	    }
31	
32	    for u in &members {
33	        for (v, kind) in outgoing_edges(u) {
34	            if members.contains(&v)
35	                && matches!(kind, DepKind::Runtime | DepKind::Build | DepKind::Optional)
36	            {
37	                adj.get_mut(&v).unwrap().push(u.clone());
38	                *in_degree.get_mut(u).unwrap() += 1;
39	            }
40	        }
41	    }
42	
43	    let mut queue: BTreeSet<PackageId> = BTreeSet::new();
44	    for (u, &deg) in &in_degree {
45	        if deg == 0 {
46	            queue.insert(u.clone());
47	        }
48	    }
49	
50	    let mut sorted = Vec::new();
51	    while let Some(u) = queue.pop_first() {
52	        sorted.push(u.clone());
53	        if let Some(neighbors) = adj.get(&u) {
54	            for v in neighbors {
55	                let deg = in_degree.get_mut(v).unwrap();
56	                *deg -= 1;
57	                if *deg == 0 {
58	                    queue.insert(v.clone());
59	                }
60	            }
61	        }
62	    }
63	
64	    if sorted.len() < members.len() {
65	        let set: HashSet<PackageId> = sorted.iter().cloned().collect();
66	        let remaining: Vec<PackageId> = members.into_iter().filter(|m| !set.contains(m)).collect();
67	        let cycle = extract_cycle(&remaining, &adj);
68	        return Err(GraphError::Cycle { cycle });
69	    }
70	
71	    Ok(sorted)
72	}
