74	fn extract_cycle(
75	    remaining: &[PackageId],
76	    adj: &BTreeMap<PackageId, Vec<PackageId>>,
77	) -> Vec<PackageId> {
78	    use petgraph::algo::tarjan_scc;
79	    use petgraph::graph::DiGraph;
80	
81	    let mut graph = DiGraph::<PackageId, ()>::new();
82	    let mut node_map = BTreeMap::new();
83	    let mut rev_map = BTreeMap::new();
84	
85	    for pkg in remaining {
86	        let idx = graph.add_node(pkg.clone());
87	        node_map.insert(pkg.clone(), idx);
88	        rev_map.insert(idx, pkg.clone());
89	    }
90	
91	    for u in remaining {
92	        if let Some(neighbors) = adj.get(u) {
93	            for v in neighbors {
94	                if let (Some(&u_idx), Some(&v_idx)) = (node_map.get(u), node_map.get(v)) {
95	                    graph.add_edge(u_idx, v_idx, ());
96	                }
97	            }
98	        }
99	    }
100	
101	    let sccs = tarjan_scc(&graph);
102	    for scc in sccs {
103	        let is_self_loop = scc.len() == 1 && graph.contains_edge(scc[0], scc[0]);
104	        if scc.len() > 1 || is_self_loop {
105	            let mut cycle = Vec::new();
106	            let start_idx = scc[0];
107	            let mut curr = start_idx;
108	            let scc_set: std::collections::HashSet<_> = scc.iter().copied().collect();
109	
110	            cycle.push(rev_map[&curr].clone());
111	            loop {
112	                let mut next_found = None;
113	                for neighbor in graph.neighbors(curr) {
114	                    if scc_set.contains(&neighbor) {
115	                        next_found = Some(neighbor);
116	                        break;
117	                    }
118	                }
119	
120	                if let Some(next) = next_found {
121	                    curr = next;
122	                    cycle.push(rev_map[&curr].clone());
123	                    if curr == start_idx {
124	                        break;
125	                    }
126	                } else {
127	                    break;
128	                }
129	            }
130	
131	            if cycle.len() > 1 {
132	                return cycle;
133	            }
134	        }
135	    }
136	
137	    remaining.to_vec()
138	}
