        } else if id == &pkg_b {
            vec![(pkg_c.clone(), DepKind::Runtime)]
        } else {
            vec![(pkg_a.clone(), DepKind::Runtime)]
        }
    });

    assert!(res.is_err());
    let err = res.unwrap_err();
    let err_str = err.to_string();
    assert!(
        err_str.contains("cycle") || err_str.contains("circular"),
        "Error must diagnose cycle: {err_str}"
    );
}

