/// Computes the order packages must be published in.
///
/// This is deliberately **not** a general-purpose "topological sort of the
/// dependency graph" (that already exists as [`toposort_impl`], reused
/// here) — it exists because `cargo publish` (run without `--no-verify`,
/// see `publish_client.rs`) re-extracts the packaged tarball and does a
/// real local build to verify it, which needs *every* dependency in the
/// crate's `Cargo.toml` resolvable from the registry, `[dev-dependencies]`
/// included. A dev-dependency on a workspace sibling being published in the
/// same batch therefore still needs that sibling to publish first, even
/// though a dev-dependency edge is correctly excluded from cascade/version
/// bump propagation (`toposort_impl`'s own default filter) since a
/// dev-only change doesn't affect the published crate's own behavior.
///
/// Only `[dependencies]`, `[build-dependencies]`, and `[dev-dependencies]`
/// are treated as ordering constraints (`Runtime`/`Build`/`Dev`); a `Peer`
/// edge does not gate publish order — a peer is expected to be resolvable
/// via the ecosystem's own version-range semantics without needing to be
/// published first (§CL.3's `PeerEscalation` distinction is exactly this).
/// `Optional` is included because an optional dependency is still a real
/// `[dependencies]`/`[optional-dependencies]` entry the packaged manifest
/// declares, and thus still something `cargo publish`'s verification build
/// can be asked to resolve.
fn publish_order<D: DependencyResolver + ?Sized>(
    resolver: &D,
    subset: &HashSet<PackageId>,
) -> Result<Vec<PackageId>, GraphError> {
    let all_pkg_ids: Vec<PackageId> = resolver.packages().map(|p| p.id.clone()).collect();
    toposort_impl(subset, &all_pkg_ids, |id| {
        resolver
            .dependencies_of(id)
            .filter(|e| matches!(e.kind, DepKind::Runtime | DepKind::Build | DepKind::Optional))
            .map(|e| (e.to.clone(), e.kind))
            .collect()
    })
}

